```sparql
PREFIX lad: <https://example.org/ladder/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?e ?name ?lei ?country ?type ?parent ?src WHERE {
  ?e a lad:Entity .
  OPTIONAL {?e lad:name ?name}
  OPTIONAL {?e lad:lei ?lei}
  OPTIONAL {?e lad:country ?country}
  OPTIONAL {?e lad:entityType ?type}
  OPTIONAL {?e lad:parent ?parent}
  OPTIONAL {?e lad:sourceSystem ?src}
} ORDER BY ?e
```

```sparql
PREFIX lad: <https://example.org/ladder/>
SELECT ?i ?desc ?iss ?gua ?ccy ?sen ?mat WHERE {
  ?i a lad:Instrument .
  OPTIONAL {?i lad:description ?desc} OPTIONAL {?i lad:issuer ?iss} OPTIONAL {?i lad:guarantor ?gua}
  OPTIONAL {?i lad:currency ?ccy} OPTIONAL {?i lad:seniority ?sen} OPTIONAL {?i lad:maturity ?mat}
  FILTER(regex(str(?i),"ladder/I(0[1-9]|1[0-9])$") || BOUND(?gua) || regex(?desc,"Cross|Corvenia|Kestrel"))
} ORDER BY ?i LIMIT 60
```

```sparql
PREFIX lad: <https://example.org/ladder/>
SELECT ?thing ?type ?basis ?date ?action ?rating ?outlook ?watch ?comment WHERE {
