Further queries are needed for the ceiling, group and guarantor questions.

```sparql
PREFIX lad: <https://example.org/ladder/>
SELECT DISTINCT ?rr ?c ?r WHERE {
 ?a lad:ratedThing ?t; lad:ratingType lad:type-LTIDR; lad:ccyBasis lad:basis-FC; lad:date ?d; lad:rating ?r .
 FILTER(STR(?d)<="2026-10-01")
 ?t lad:sourceSystem ?s . FILTER(STR(?s)!="QA")
 ?t lad:lei ?l ; lad:country ?ct .
 OPTIONAL { ?rs lad:lei ?l ; lad:sourceSystem ?ss ; lad:country ?cr . FILTER(STR(?ss)="RESEARCH") }
 BIND(COALESCE(?cr,?ct) AS ?c)
 FILTER(STR(?c)="CV" || STR(?c)="VD")
 FILTER NOT EXISTS { ?a2 lad:ratedThing ?t2; lad:ratingType lad:type-LTIDR; lad:ccyBasis lad:basis-FC; lad:date ?d2 . ?t2 lad:lei ?l . FILTER(STR(?d2)>STR(?d) && STR(?d2)<="2026-10-01") }
 ?rr lad:lei ?l ; lad:sourceSystem ?s3 . FILTER(STR(?s3)="RATINGS")
}
```

